import{At as e,Et as t,dt as n,ft as r,lt as i,n as a,ot as o,ut as s}from"./chunks/framework.8UxoGp64.js";var c=JSON.parse(`{"title":"Statistic 统计数值","description":"","frontmatter":{},"headers":[],"relativePath":"components/statistic.md","filePath":"components/statistic.md","lastUpdated":1791177194000}`),l={name:`components/statistic.md`};function u(a,c,l,u,d,f){let p=e(`XhDemo`);return t(),i(`div`,null,[c[0]||=s(`<h1 id="statistic-统计数值" tabindex="-1">Statistic 统计数值 <a class="header-anchor" href="#statistic-统计数值" aria-label="Permalink to “Statistic 统计数值”">​</a></h1><p>带标签的关键数字，可以配前后缀。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/statistic" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/statistic.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/statistic" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/statistic" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/statistic.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h2><p>标签在上、数值在下；数值由使用者格式化后放入，组件不做千分位也不做换算</p>`,5),r(p,{src:`statistic/01-basic`}),c[1]||=s(`<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to “组件结构”">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;statistic&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <code>value</code> · <code>prefix</code> · <code>suffix</code> · <code>trend</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><h3 id="前后缀" tabindex="-1">前后缀 <a class="header-anchor" href="#前后缀" aria-label="Permalink to “前后缀”">​</a></h3><p>prefix 与 suffix 和数值排在同一行、按基线对齐，比数值小一档</p>`,6),r(p,{src:`statistic/02-affix`}),c[2]||=o(`h3`,{id:`尺寸`,tabindex:`-1`},[n(`尺寸 `),o(`a`,{class:`header-anchor`,href:`#尺寸`,"aria-label":`Permalink to “尺寸”`},`​`)],-1),c[3]||=o(`p`,null,`size 改变标签、数值与前后缀的字号，不传 size 即默认档`,-1),r(p,{src:`statistic/03-size`}),c[4]||=o(`h3`,{id:`颜色`,tabindex:`-1`},[n(`颜色 `),o(`a`,{class:`header-anchor`,href:`#颜色`,"aria-label":`Permalink to “颜色”`},`​`)],-1),c[5]||=o(`p`,null,`tone 决定数值与前后缀使用哪族颜色，标签始终保持弱前景`,-1),r(p,{src:`statistic/04-tone`}),c[6]||=o(`h3`,{id:`等宽数字`,tabindex:`-1`},[n(`等宽数字 `),o(`a`,{class:`header-anchor`,href:`#等宽数字`,"aria-label":`Permalink to “等宽数字”`},`​`)],-1),c[7]||=o(`p`,null,`数值使用等宽数字排版，反复更换数值时字宽不变，后面的单位不会左右移动`,-1),r(p,{src:`statistic/05-tabular`}),c[8]||=o(`h3`,{id:`涨跌`,tabindex:`-1`},[n(`涨跌 `),o(`a`,{class:`header-anchor`,href:`#涨跌`,"aria-label":`Permalink to “涨跌”`},`​`)],-1),c[9]||=o(`p`,null,`trend 写为 trend 部件的 data-direction，箭头由皮肤绘制；与 tone 正交：下跌也可以是正向语气`,-1),r(p,{src:`statistic/06-trend`}),c[10]||=s(`<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to “设计指引”">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h3><ul><li>仪表盘、概览页上的核心指标。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to “何时不用”">​</a></h3><ul><li>多个指标需要按维度对照时，使用<a href="./table">表格</a>。</li><li>表达完成比例时，使用<a href="./progress">进度条</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li>标签、值、前缀、后缀各占一段。</li><li>数字使用等宽字形，位数变化时不会左右晃动。</li><li><code>trend</code> 给出涨跌方向，箭头由皮肤绘制；它与 <code>tone</code> 正交，下跌也可以是正向语气。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to “组合”">​</a></h3><ul><li>值位放<a href="./number-animation">数值动画</a>；整块放入<a href="./card">卡片</a>；一排指标使用<a href="./grid">栅格</a>。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><ul><li>单位写进后缀而不是混入数字，数字才能对齐。</li><li>给出对比基准（同比、环比），单独一个数字无法判断好坏。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to “反模式”">​</a></h3><ul><li>一屏内十几个同等大小的指标，没有重点。</li><li>显示精确到分的金额却不提供货币符号。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to “API 参考”">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to “产物”">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-statistic&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhStatisticLabel</code> <code>XhStatisticPrefix</code> <code>XhStatisticRoot</code> <code>XhStatisticSuffix</code> <code>XhStatisticTrend</code> <code>XhStatisticValue</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/statistic.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to “Props”">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，只写为 root 的 data-size。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，只写为 root 的 data-tone。</td></tr><tr><td><code>trend</code></td><td><code>StatisticTrend</code></td><td></td><td>涨跌：up / down / flat，写为 trend 部件的 data-direction，皮肤据此绘制兜底箭头。 与 tone 正交，方向与颜色互不联动：下跌也可以是正面信息（差错率、退货率）。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to “connect API”">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>trend</code></td><td><code>StatisticTrend</code></td><td>当前涨跌方向；未提供时为 undefined。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getValueProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPrefixProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSuffixProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTrendProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to “无障碍”">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to “键盘”">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to “样式参考”">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to “皮肤”">​</a></h3><p><code>@xihan-ui/styles/statistic.css</code> 按 <code>[data-scope=&quot;statistic&quot;][data-part=&quot;root&quot;]</code> 部件选择器书写，发布产物以挂载类 <code>.xh-scope-statistic</code> 代替其中的 data-scope（特异性相同），位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>，部件选择器照常可用。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to “数据属性”">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>trend</code></td><td><code>data-direction</code></td><td>props.trend</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to “CSS 变量”">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-statistic-affix-fg</code></td><td><code>prefix</code><br><code>suffix</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_tone-fg</code></td><td>statistic 的 prefix、suffix 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-statistic-affix-font-size</code></td><td><code>prefix</code><br><code>suffix</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_statistic-affix-size</code></td><td>statistic 的 prefix、suffix 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-statistic-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>statistic 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-statistic-gap</code></td><td><code>root</code></td><td><code>column-gap</code></td><td><code>default</code></td><td><code>--xh-space-0</code></td><td>statistic 的 root 部件 column-gap 覆盖槽。</td></tr><tr><td><code>--xh-statistic-icon-size</code></td><td><code>root</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_statistic-icon-size</code></td><td>statistic 的 root 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-statistic-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>statistic 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-statistic-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_statistic-label-size</code></td><td>statistic 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-statistic-row-gap</code></td><td><code>root</code></td><td><code>row-gap</code></td><td><code>default</code></td><td><code>--xh-_statistic-row-gap</code></td><td>statistic 的 root 部件 row-gap 覆盖槽。</td></tr><tr><td><code>--xh-statistic-trend-fg</code></td><td><code>trend</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_tone-fg</code></td><td>statistic 的 trend 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-statistic-trend-font-size</code></td><td><code>trend</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_statistic-affix-size</code></td><td>statistic 的 trend 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-statistic-trend-gap</code></td><td><code>trend</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>statistic 的 trend 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-statistic-trend-offset</code></td><td><code>trend</code></td><td><code>margin-inline-start</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>statistic 的 trend 部件 margin-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-statistic-value-fg</code></td><td><code>value</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_tone-fg</code></td><td>statistic 的 value 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-statistic-value-font-size</code></td><td><code>value</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_statistic-value-size</code></td><td>statistic 的 value 部件 font-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to “动效”">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to “RTL”">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>`,39)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};